def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # L-piece color is determined by its missing corner.
    l_colors = {
        frozenset({(0, 1), (1, 0), (1, 1)}): 2,  # missing top-left
        frozenset({(0, 0), (1, 0), (1, 1)}): 4,  # missing top-right
        frozenset({(0, 0), (0, 1), (1, 1)}): 3,  # missing bottom-left
        frozenset({(0, 0), (0, 1), (1, 0)}): 2,  # missing bottom-right
    }

    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset((r+i, c+j) for i in (0, 1) for j in (0, 1))
            placements.append((square, 1))
            for shape, color in l_colors.items():
                piece = frozenset((r+i, c+j) for i, j in shape)
                placements.append((piece, color))

    by_cell = {cell: [] for cell in cells}
    for piece, color in placements:
        if piece <= cells:
            for cell in piece:
                by_cell[cell].append((piece, color))

    def search(left, chosen):
        if not left:
            return chosen
        cell = min(left, key=lambda p: sum(piece <= left for piece, _ in by_cell[p]))
        for piece, color in by_cell[cell]:
            if piece <= left:
                result = search(left - piece, chosen + [(piece, color)])
                if result is not None:
                    return result
        return None

    solution = search(cells, [])
    if solution:
        for piece, color in solution:
            for r, c in piece:
                out[r][c] = color
    return out
